            return FfiConverterOptionalString.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_grouse_core_fn_method_core_active_session_id(
        it,
        _status)
}
    }
    )
    }
    

    
