/**
 * @suppress
 */
public object FfiConverterTypeGrouseUnstable: FfiConverter<GrouseUnstable, Long> {
    override fun lower(value: GrouseUnstable): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): GrouseUnstable {
        return GrouseUnstable(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): GrouseUnstable {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: GrouseUnstable) = 8UL

    override fun write(value: GrouseUnstable, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



