    var `cwd`: kotlin.String
    , 
    var `autoConnect`: kotlin.Boolean
    , 
    /**
     * `_meta.client`, e.g. "grouse-desktop" | "grouse" | "grouse-cli".
     */
    var `clientId`: kotlin.String
    , 
    /**
