/**
 * Stable events, one method per family (CONTRACT §3.2).
 */
public interface CoreListener {
    
    fun `onStatus`(`status`: ConnectionStatus)
    
    fun `onSessions`(`sessions`: List<SessionSummary>)
    
    fun `onTranscript`(`event`: TranscriptEvent)
    
    fun `onStream`(`event`: StreamEvent)
    
    fun `onConfig`(`options`: List<ConfigOption>)
    
    fun `onPermissionRequest`(`request`: PermissionRequest)
    
    fun `onSessionTouched`(`sessionId`: kotlin.String, `title`: kotlin.String, `updatedAt`: kotlin.String)
    
    fun `onProjects`(`projects`: List<ProjectSummary>)
    
    /**
     * A roam peer's lifecycle line (CONTRACT §6).
     */
    fun `onRoamPeerStatus`(`label`: kotlin.String, `status`: kotlin.String)
    
    /**
     * A roam peer's `session/list` result, ids prefixed `roam:<peer>:<id>`.
     */
    fun `onRoamSessions`(`label`: kotlin.String, `sessions`: List<SessionSummary>)
    
    /**
     * A fresh session created on a roam peer (`session/new` reply), raw id
     * (NOT prefixed — the UI prefixes it for routing).
     */
    fun `onPeerNewSession`(`label`: kotlin.String, `sessionId`: kotlin.String)
    
    /**
     * The live turn's run id for a session, or empty when the run ended
     * (gap 1: makes session/steer reachable).
     */
    fun `onActiveRun`(`sessionId`: kotlin.String, `runId`: kotlin.String)
    
    /**
     * Slash commands the server can execute right now (gap 2: autocomplete).
     */
    fun `onCommands`(`commands`: List<kotlin.String>)
    
    companion object
}



